from h import *
O=[]
O.append(R(6317081,
("Bacalao con especias marroquíes y tiras de zanahoria","Este bacalao con especias marroquíes está impregnado de especias cálidas y aromáticas y se acompaña con tiernas tiras de zanahoria para una comida ligera pero satisfactoria. Asar las zanahorias debajo del pescado añade sabor y mantiene el plato sencillo y práctico. Es una opción nutritiva, baja en carbohidratos, muy baja en carbohidratos y baja en grasa, ideal para las personas con diabetes que buscan algo lleno de vida.","4","4 onzas de bacalao y 1 taza de tiras de zanahoria",
["aproximadamente 4 porciones de filetes de bacalao","4 zanahorias medianas (peladas en tiras)","1 cucharada de aceite de oliva","1/2 limón, el jugo","1/2 cucharadita de comino molido","1/2 cucharadita de cilantro molido","1/4 de cucharadita de pimentón","1/8 de cucharadita de canela molida","1/4 de cucharadita de sal","1/4 de cucharadita de pimienta negra","2 cucharadas de cilantro fresco o perejil (picado)"],
["Precaliente el horno a 375 grados F. Forre una bandeja para hornear con papel pergamino.","En un tazón pequeño, mezcle el comino, el cilantro molido, el pimentón, la canela, la sal y la pimienta.","Frote la mezcla de especias sobre los filetes de bacalao. Reserve.","Mezcle las tiras de zanahoria con el aceite de oliva y una pizca de sal. Extiéndalas sobre la bandeja para hornear y coloque encima los filetes de bacalao.","Hornee de 15 a 18 minutos, o hasta que el bacalao se desmenuce fácilmente con un tenedor y las zanahorias estén tiernas pero crujientes.","Termine con un chorrito de limón y un poco de hierbas frescas espolvoreadas antes de servir."],[],[]),
("سمك القد بالتوابل المغربية مع شرائح الجزر","يتشبّع سمك القد هذا بالتوابل المغربية الدافئة والعطرية ويُقدَّم مع شرائح الجزر الطرية لوجبة خفيفة ومشبعة في آن واحد. يضيف تحميص الجزر تحت السمك نكهة مميزة ويحافظ على بساطة الطبق وسهولته. إنها وجبة غنية بالعناصر الغذائية، قليلة الكربوهيدرات، وقليلة جدًا الكربوهيدرات، وقليلة الدهون، ومثالية لمرضى السكري الباحثين عن طبق نابض بالحيوية.","4","4 أونصات من سمك القد و1 كوب من شرائح الجزر",
["حوالي 4 حصص من فيليه سمك القد","4 حبات جزر متوسطة (مقشّرة على شكل شرائح طويلة)","1 ملعقة كبيرة زيت زيتون","½ حبة ليمون، عصيرها","½ ملعقة صغيرة كمون مطحون","½ ملعقة صغيرة كزبرة مطحونة","¼ ملعقة صغيرة بابريكا","⅛ ملعقة صغيرة قرفة مطحونة","¼ ملعقة صغيرة ملح","¼ ملعقة صغيرة فلفل أسود","2 ملعقة كبيرة كزبرة خضراء أو بقدونس (مفروم)"],
["سخّن الفرن مسبقًا إلى 375° فهرنهايت (190° مئوية). بطّن صينية خبز بورق الزبدة.","في وعاء صغير، اخلط الكمون والكزبرة المطحونة والبابريكا والقرفة والملح والفلفل.","افرك خليط التوابل على شرائح سمك القد. اتركها جانبًا.","قلّب شرائح الجزر مع زيت الزيتون ورشة من الملح. وزّعها على صينية الخبز وضع فيليه سمك القد فوقها.","اخبزها لمدة 15-18 دقيقة، أو حتى يتفتت سمك القد بسهولة بالشوكة ويصبح الجزر طريًا ومقرمشًا قليلًا.","أنهِ الطبق بعصرة ليمون ورشّة من الأعشاب الطازجة قبل التقديم."],[],[])))
O.append(R(6318845,None,
("سموذي فطيرة القرع","يُعد سموذي القرع هذا حلوى فريدة ولذيذة لموسم الأعياد.","1","1 كوب سموذي",
["⅓ كوب زبادي يوناني سادة خالي الدسم (خالي الدسم)","1 ملعقة كبيرة + ¼ ملعقة صغيرة للتزيين من بذور الكتان المطحونة (مقسّمة)","½ كوب هريس القرع","½ كوب حليب اللوز غير المحلى","¼ ملعقة صغيرة بهارات فطيرة القرع","2 مكعب ثلج (مجروش)","2 ملعقة كبيرة كريمة مخفوقة للتزيين (خالية من الدهون)"],
["اخلط الزبادي اليوناني و1 ملعقة كبيرة من بذور الكتان المطحونة وهريس القرع وحليب اللوز وبهارات فطيرة القرع والثلج في الخلاط. اخلطها حتى تصبح ناعمة.","اسكب السموذي في كوب، وزيّنه بالكريمة المخفوقة ورشّ فوقه ¼ ملعقة صغيرة من بذور الكتان المطحونة."],[],[])))
O.append(R(6319828,None,
("معكرونة بالجبن بالقرنبيط (\"ماك\") مع الكركند","هذه النسخة الأقل كربوهيدرات من معكرونة الكركند الفاخرة بالجبن تتميز بزهيرات القرنبيط بالجبن ذات الوجه المقرمش وبلحم الكركند الطري المسلوق بهدوء.","8","⅛ من الطاجن",
["1 بخّة (0.25 غرام) من بخاخ الطهي غير اللاصق","1 رأس قرنبيط (مقطّع إلى زهيرات (8 أكواب من الزهيرات))","5 أكواب ماء","2 ذيل كركند مجمد وزن كل منهما 4 أونصات أو 1 كوب من لحم الكركند الصناعي المفروم","1 ملعقة كبيرة زيت زيتون","2 ملعقة كبيرة دقيق متعدد الاستخدامات","2 كوب حليب (خالي الدسم)","⅛ ملعقة صغيرة جوزة الطيب المطحونة","½ ملعقة صغيرة ملح","¼ ملعقة صغيرة فلفل أسود","¼ ملعقة صغيرة صلصة حارة","3 أونصات جبن كولبي جاك (قليل الدسم)","4 أونصات جبن كريمي (خالي الدسم)","½ كوب فتات خبز بانكو من القمح الكامل"],
["سخّن الفرن مسبقًا إلى 350° فهرنهايت (175° مئوية). ادهن طبق خبز زجاجيًا بقياس 9×13 بوصة ببخاخ الطهي. اتركه جانبًا.","ضع زهيرات القرنبيط في طبق كبير صالح للميكروويف. اسكب 1 كوب من الماء فوق القرنبيط وغطِّه. سخّنه في الميكروويف لمدة 12 دقيقة أو حتى يلين القرنبيط. صفّه ثم أبقه دافئًا.","أثناء تسخين القرنبيط في الميكروويف: إذا كنت تستخدم ذيول الكركند، فاترك 4 أكواب من الماء حتى تغلي ثم خفّض الحرارة حتى يبقى الماء بالكاد يغلي بهدوء. أضف ذيول الكركند إلى الماء واسلقها بهدوء لمدة 7 دقائق. أخرج الذيول من الماء لتبرد قليلًا. اقطع ذيول الكركند، واستخرج اللحم منها وافرمه. تحصل على حوالي كوب من لحم الكركند.","ضع زيت الزيتون في قدر على حرارة متوسطة. أضف الدقيق واطهه مع التحريك المستمر لمدة 2 دقيقة. أضف الحليب مع الخفق. أضف جوزة الطيب والملح والفلفل والصلصة الحارة. اتركه حتى يغلي، ثم خفّض الحرارة واتركه على نار هادئة لمدة 3 دقائق.","أضف جبن كولبي جاك والجبن الكريمي وحرّك حتى يذوبا.","ضع القرنبيط في طبق الخبز. استخدم شوكة لتفتيت الزهيرات إلى قطع بحجم 1 بوصة أو أصغر.","اسكب صلصة الجبن فوق القرنبيط وحرّك ليتغطى بها.","انثر الكركند فوق القرنبيط وحرّك ليتغطى بالصلصة.","انثر فتات خبز البانكو بالتساوي على وجه الطاجن ثم رشّ وجه البانكو ببخاخ الطهي.","اخبزه لمدة 30 دقيقة."],[],[])))
O.append(R(6320059,None,
("أرز بري مع التوت البري واللوز","يستغرق الأرز البري وقتًا أطول في الطهي من الأنواع الأخرى من الأرز، لكن مؤشره السكري أقل ويبلغ 45 مقارنة بالأرز الأبيض الذي يبلغ مؤشره السكري 70. هذا الأرز طبق جانبي رائع للأعياد كذلك ومناسب للتجمعات الكبيرة، إذ يكفي لـ 11 حصة.","11","حوالي ½ كوب",
["1 ملعقة كبيرة زيت زيتون","1 حبة بصل صغيرة (مقطّعة مكعبات)","3½ أكواب ماء","1 كوب مرق دجاج قليل الصوديوم (خالٍ من الدهن، منخفض الصوديوم)","8 أونصات أرز بري","⅓ كوب لوز شرائح (محمّص)","⅓ كوب توت بري (مجفف)"],
["سخّن الزيت في قدر كبير على حرارة متوسطة. أضف البصل واطهه لمدة 3 إلى 4 دقائق.","أضف الماء ومرق الدجاج إلى القدر واتركه حتى يغلي.","أضف الأرز؛ غطِّ القدر واطهه حسب تعليمات العبوة؛ عادةً حوالي 50-60 دقيقة.","ارفع الغطاء وأضف اللوز المحمّص والتوت البري؛ واخلطها معًا بشوكة."],[],[])))
O.append(R(6320079,
("Ensalada saludable bañada por el sol","Cremosa, crujiente, ácida y llena de proteína: ¡esta ensalada lo tiene todo! Licuar el aguacate en el aderezo lo vuelve rico y cremoso, y los cítricos hacen que parezca verano en cualquier época del año. La quinua, el edamame y las pepitas aportan proteína, por lo que es una ensalada sustanciosa que combina muy bien con un sándwich o una sopa en el almuerzo. Encuentre esta receta y muchas más en nuestro libro de cocina Guilt-Free Comfort Favorites, de la cocina de pruebas de Mr. Food.","6","1 1/2 tazas",
["2 cucharadas de aceite de oliva","2 cucharadas de jugo de limón","2 cucharadas de jugo de naranja","1 aguacate entero (dividido, sin semilla, pelado y cortado en cubitos)","1/4 de taza de perejil fresco (sin tallos)","1/4 de cucharadita de sal","1 diente de ajo","1 lechuga bibb o mantecosa entera (cortada en trozos de 1 pulgada)","1 taza de tomates uva o cherry (cortados por la mitad)","1/2 taza de quinua (cocida según las instrucciones del paquete y enfriada)","1 taza de edamame congelado sin cáscara (cocido según las instrucciones del paquete)","2 cucharadas de pepitas sin sal"],
["Prepare el aderezo de cítricos: en una licuadora o procesador de alimentos, licue el aceite de oliva, el jugo de limón, el jugo de naranja, 1/4 del aguacate, el perejil, la sal y el ajo hasta obtener una mezcla suave. Reserve.","En un tazón grande, combine la lechuga, el tomate, la quinua, el edamame, el resto del aguacate y las pepitas. Vierta el aderezo sobre la ensalada y mezcle con suavidad. Sirva de inmediato o refrigere hasta el momento de servir."],[],[]),
("سلطة الصحة المشمسة","كريمية ومقرمشة وحامضة ومليئة بالبروتين، هذه السلطة تجمع كل شيء! يمنح خلط الأفوكادو في الصلصة قوامًا غنيًا وكريميًا، وتجعل إضافة الحمضيات الأجواء تبدو صيفية في أي وقت من السنة. تضيف الكينوا والإدامامي وبذور اليقطين البروتين، فتصبح سلطة مشبعة تناسب تمامًا مرافقة شطيرة أو حساء في وجبة الغداء! ستجد هذه الوصفة وغيرها في كتاب الطبخ الخاص بنا Guilt-Free Comfort Favorites من مطبخ تجارب Mr. Food.","6","1½ كوب",
["2 ملعقة كبيرة زيت زيتون","2 ملعقة كبيرة عصير ليمون","2 ملعقة كبيرة عصير برتقال","1 حبة أفوكادو كاملة (مقسّمة، منزوعة النواة ومقشّرة ومقطّعة مكعبات)","¼ كوب بقدونس طازج (بدون سيقان)","¼ ملعقة صغيرة ملح","1 فص ثوم","1 رأس خس بيب أو بوسطن كامل (مقطّع إلى قطع بحجم 1 بوصة)","1 كوب طماطم عنبية أو كرزية (مقطّعة إلى نصفين)","½ كوب كينوا (مطبوخة حسب تعليمات العبوة ومبرّدة)","1 كوب إدامامي مجمد منزوع القشر (مطبوخ حسب تعليمات العبوة)","2 ملعقة كبيرة بذور يقطين غير مملحة"],
["حضّر صلصة الحمضيات: في الخلاط أو محضّر الطعام، اخلط زيت الزيتون وعصير الليمون وعصير البرتقال و¼ حبة الأفوكادو والبقدونس والملح والثوم حتى تصبح ناعمة. اتركها جانبًا.","في وعاء كبير، اخلط الخس والطماطم والكينوا والإدامامي وباقي الأفوكادو وبذور اليقطين. اسكب الصلصة فوق السلطة وقلّبها برفق. قدّمها فورًا أو برّدها حتى وقت التقديم."],[],[])))
O.append(R(6320177,None,
("بروكلي بالأمنديين","هل جرّبت الفاصوليا الخضراء بالأمنديين؟ جرّب الآن البروكلي بالأمنديين! يحتوي اللوز والمكسرات على الدهون الأحادية غير المشبعة والدهون المتعددة غير المشبعة الأفضل لصحة القلب. توصي جمعية القلب الأمريكية بتناول 4 حصص على الأقل أسبوعيًا من المكسرات أو البقوليات أو البذور.","6","½ كوب",
["1 بخّة (0.25 غرام) من بخاخ الطهي غير اللاصق","12 أونصة زهيرات بروكلي","1½ ملعقة كبيرة زيت زيتون","2 فص ثوم (مفروم)","3 ملعقة كبيرة لوز شرائح","⅛ ملعقة صغيرة فلفل أسود","1 ملعقة كبيرة عصير ليمون"],
["سخّن الفرن مسبقًا إلى 425° فهرنهايت (220° مئوية). رشّ صينية خبز ببخاخ الطهي.","في وعاء صغير اخلط البروكلي وزيت الزيتون والثوم واللوز والفلفل الأسود. اسكب الخليط على صينية الخبز.","اخبزه لمدة 10-12 دقيقة حتى تصبح رؤوس البروكلي بنية قليلًا.","اسكب البروكلي في وعاء ورشّ عليه عصير الليمون."],[],[])))
O.append(R(6320230,None,
("سلطة أورزو اليونانية بالبازلاء والليمون وزيتون كالاماتا","أضف دجاجًا مشويًا على السيخ أو روبيانًا مشويًا لتحويل هذه السلطة إلى طبق رئيسي. وإلا فيمكن تقديمها كطبق جانبي لذيذ يكمّل الدجاج أو السمك المشوي.","6","1/6 من الوصفة",
["6 أونصات أورزو من القمح الكامل (مسلوقة حتى تكون متماسكة قليلًا، مصفّاة ومشطوفة بالماء البارد)","1 كوب خيار إنجليزي (مقطّع مكعبات بحجم ½ بوصة)","1 كوب طماطم (مقطّعة)","½ كوب بصل أحمر (مقطّع (نصف حبة بصل متوسطة))","¼ كوب زيتون كالاماتا (منزوع النواة ومقطّع)","2 ملعقة كبيرة شبت طازج (مفروم ناعمًا طازجًا)","3 أونصات جبن فيتا (قليل الدسم، مفتّت)","½ كوب بازلاء مجمدة (مذابة)","1 ملعقة كبيرة عصير ليمون (طازج)","2½ ملعقة كبيرة زيت زيتون بكر ممتاز","1 ملعقة صغيرة أوريجانو مجفف (مجفف)","1 كوب أوراق سبانخ صغيرة (مكدّس)"],
["اخلط جميع المكونات ما عدا أوراق السبانخ في وعاء كبير. اتركها في الثلاجة مغطاة لمدة ساعة واحدة على الأقل قبل التقديم لتتشرب النكهات. أضف أوراق السبانخ قبل التقديم مباشرة."],[],[])))
O.append(R(6320927,
("Tostada de mantequilla de almendras con pera fresca","Disfrute de un comienzo dulce y salado para su día. Esta tostada de mantequilla de almendras con peras frescas es una combinación armoniosa de almendras con su sabor a nuez y duraznos brillantes, con un toque de canela picante. Disfrute otra versión de este desayuno en verano, cuando los duraznos maduros y sabrosos están de temporada.","4","1 tostada",
["4 rebanadas de pan integral","1/4 de taza de mantequilla de almendras","1 pera mediana (en rodajas)","1/2 cucharadita de canela molida"],
["Tueste el pan y unte la mantequilla de almendras.","Cubra con las rodajas de pera y espolvoree con la canela."],[],[]),
("توست زبدة اللوز مع الكمثرى الطازجة","استمتع ببداية حلوة ومالحة ليومك. توست زبدة اللوز مع الكمثرى الطازجة هذا مزيج متناغم من اللوز بنكهة المكسرات والخوخ الزاهي، مع لمسة من القرفة الحارة. استمتع بنسخة أخرى من هذا الفطور في الصيف عندما يكون الخوخ الناضج والغني بالنكهة في موسمه.","4","1 قطعة توست",
["4 شرائح خبز بالحبوب الكاملة","¼ كوب زبدة اللوز","1 حبة كمثرى متوسطة (مقطّعة شرائح)","½ ملعقة صغيرة قرفة مطحونة"],
["حمّص الخبز وادهنه بزبدة اللوز.","غطِّه بشرائح الكمثرى ورشّ عليه القرفة."],[],[])))
O.append(R(6321052,None,
("فريتاتا سريعة بنقانق الديك الرومي والريحان الطازج","الفريتاتا خيار رائع للفطور ويمكن طهيها بكميات كبيرة لتحضير عدة حصص وتوزيعها على أيام الأسبوع.","4","¼ شريحة مثلثة من الفريتاتا",
["1 بخّة (0.25 غرام) من بخاخ الطهي غير اللاصق","8 أونصات نقانق ديك رومي قليلة الصوديوم (مقطّعة مكعبات)","1½ كوب بديل البيض","¾ أونصة جبن موزاريلا (قليلة الدسم، مبشورة)","½ كوب بصل أخضر (مقطّع ناعمًا)","1 كوب طماطم (مقطّعة مكعبات)","¼ كوب ريحان طازج (مفروم)"],
["رشّ مقلاة كبيرة غير لاصقة رشًّا خفيفًا ببخاخ الطهي. اضبطها على حرارة متوسطة. أضف النقانق واطهها لمدة 3 دقائق أو حتى تبدأ بالاحمرار مع التحريك من حين لآخر.","اسكب بديل البيض بالتساوي فوق النقانق واطهه لمدة دقيقة واحدة. لا تحرّكه. ثم ارفعه برفق ليسيل البيض غير المطهو إلى الأسفل. ارفعه عن النار واتركه حتى يكتمل نضجه.","رشّ الجبن والبصل الأخضر والطماطم والريحان بالتساوي على الوجه."],[],[])))
O.append(R(6321815,None,
("وعاء سموذي التوت الأزرق","هذه وصفة قليلة الدهون وقليلة جدًا الدهون ونباتية تتميز بالتوت الأزرق. يمزج وعاء سموذي التوت الأزرق هذا الزبادي اليوناني الكريمي مع الفاكهة ولمسة من التوابل لفطور منعش وغني بالعناصر الغذائية. مع الألياف من بذور الشيا والبروتين من الزبادي والحلاوة الطبيعية من الفاكهة، فهو طريقة متوازنة لبدء اليوم. إنه خيار رائع للحفاظ على مستويات طاقة ثابتة بدون سكر مضاف.","2","1 وعاء لكل حصة",
["1 كوب توت أزرق مجمد","½ كوب حليب خالي الدسم","1 حبة موز متوسطة (ناضجة)","1 كوب زبادي يوناني سادة","1 ملعقة صغيرة خلاصة الفانيليا الطبيعية","½ كوب توت أزرق طازج","2 ملعقة صغيرة جرانولا قليلة الدسم","2 ملعقة صغيرة بذور الشيا","1 ملعقة صغيرة قرفة مطحونة"],
["في الخلاط، اخلط التوت الأزرق المجمد والحليب والموز والزبادي وخلاصة الفانيليا. اخلطها حتى تصبح ناعمة وكريمية.","وزّع خليط السموذي بالتساوي بين وعاءين. زيّن كل وعاء بالتوت الأزرق الطازج ورشّة من الجرانولا قليلة الدسم وبذور الشيا ورشّة من القرفة المطحونة."],[],[])))
O.append(R(6324312,
("Tostada de aguacate con toque cítrico","Este bocadillo es un clásico cremoso y realzado con cítricos que logra el equilibrio perfecto entre lo crujiente y lo suave.","1","1 rebanada",
["1 rebanada de pan integral","1/4 de aguacate maduro","1 cucharadita de jugo de limón"],
["Tueste el pan integral hasta que alcance el punto de dorado y crujiente que prefiera.","Mientras se tuesta el pan, ponga 1/4 de aguacate en un tazón pequeño. Agregue el jugo de limón y macháquelo con un tenedor hasta que quede con trocitos o suave, según su preferencia.","Unte la mezcla machacada de manera uniforme sobre la tostada caliente.","Sirva de inmediato, mientras la tostada aún esté crujiente."],[],[]),
("توست الأفوكادو المنعش","هذه الوجبة الخفيفة كلاسيكية كريمية تتألق بالحمضيات وتحقق التوازن المثالي بين المقرمش والناعم.","1","1 شريحة",
["1 شريحة خبز بالحبوب الكاملة","¼ حبة أفوكادو ناضجة","1 ملعقة صغيرة عصير ليمون"],
["حمّص خبز الحبوب الكاملة حتى تحصل على درجة التحميص الذهبية المقرمشة التي تفضّلها.","بينما يُحمَّص الخبز، ضع ¼ حبة أفوكادو في وعاء صغير. أضف عصير الليمون واهرسه بشوكة حتى يصبح خشنًا أو ناعمًا حسب تفضيلك.","وزّع الخليط المهروس بالتساوي على التوست الدافئ.","قدّمه فورًا بينما لا يزال التوست مقرمشًا."],[],[])))
O.append(R(6325149,
("Chiles poblanos rellenos de verduras de Ingrid Hoffmann","Los chiles poblanos se usan sobre todo en la cocina mexicana. Están llenos de sabor y son ideales para rellenar con casi cualquier cosa. Tienen un toque picante, justo el suficiente para realzar el sabor.","4","1 chile poblano relleno",
["1 porción de aceite en aerosol antiadherente (0.25 g)","4 chiles poblanos grandes","1 cucharada de aceite de oliva","8 onzas de champiñones blancos (picados en trozos grandes)","1 taza de zanahorias (ralladas)","4 tallos de cebollín (en rodajas finas)","4 dientes de ajo (picados)","1/8 de cucharadita de sal","2 cucharadas de albahaca fresca (picada, o 2 cucharaditas de hojas de albahaca seca)","4 cucharadas de queso fresco (desmenuzado)"],
["Precaliente el asador del horno. Forre una bandeja para asar con papel aluminio. Rocíe ligeramente el papel aluminio con aceite en aerosol antiadherente. Coloque los chiles poblanos en la bandeja y áselos a 4 pulgadas de la fuente de calor, volteándolos de vez en cuando, hasta que estén tiernos y ligeramente chamuscados en algunas partes, unos 8 minutos.","Coloque los chiles poblanos en una bolsa plástica con cierre hermético; saque el aire y selle la bolsa. Déjelos reposar 15 minutos. Deje el asador encendido.","Caliente el aceite en una sartén grande antiadherente a fuego medio-alto. Agregue los champiñones, las zanahorias, el cebollín, el ajo y la sal, y cocine, revolviendo de vez en cuando, hasta que las verduras estén tiernas, unos 8 minutos. Retire del fuego. Incorpore la albahaca hasta que se mezcle bien.","Mientras tanto, pele los chiles poblanos. Haga un corte para crear un hueco y retire las semillas. Rellene cada chile con una cuarta parte de la mezcla de champiñones y cubra con 1 cucharada de queso.","Ase los chiles rellenos a 4 pulgadas de la fuente de calor, hasta que el relleno esté caliente y el queso empiece a derretirse, unos 4 minutos."],[],[]),
("فلفل بوبلانو المحشو بالخضار من إنجريد هوفمان","يُستخدم فلفل بوبلانو في المطبخ المكسيكي في الغالب. إنه مليء بالنكهة ومناسب جدًا للحشو بكل شيء تقريبًا. وفيه لمسة من الحرارة، تكفي تمامًا لتعزيز النكهة.","4","1 حبة بوبلانو محشوة",
["1 بخّة (0.25 غرام) من بخاخ الطهي غير اللاصق","4 حبات فلفل بوبلانو كبيرة","1 ملعقة كبيرة زيت زيتون","8 أونصات فطر أبيض (فطر الأزرار) (مفروم خشنًا)","1 كوب جزر (مبشور)","4 سيقان بصل أخضر (مقطّعة شرائح رفيعة)","4 فصوص ثوم (مفرومة)","⅛ ملعقة صغيرة ملح","2 ملعقة كبيرة ريحان طازج (مفروم، أو 2 ملعقة صغيرة من أوراق الريحان المجففة)","4 ملاعق كبيرة جبن كيسو فريسكو (مفتّت)"],
["سخّن الشواية العلوية للفرن. بطّن صينية الشواء بورق الألمنيوم. رشّ الورق رشًّا خفيفًا ببخاخ الطهي غير اللاصق. ضع حبات البوبلانو في الصينية واشوِها على بعد 4 بوصات من مصدر الحرارة مع تقليبها من حين لآخر، حتى تلين وتتفحّم قليلًا في بعض المواضع، لمدة 8 دقائق تقريبًا.","ضع حبات البوبلانو في كيس بلاستيكي بإغلاق محكم؛ اضغط لإخراج الهواء وأغلق الكيس. اتركها 15 دقيقة. أبقِ الشواية مشتعلة.","سخّن الزيت في مقلاة كبيرة غير لاصقة على حرارة متوسطة إلى عالية. أضف الفطر والجزر والبصل الأخضر والثوم والملح واطهِ مع التحريك من حين لآخر حتى تلين الخضار، لمدة 8 دقائق تقريبًا. ارفعها عن النار. أضف الريحان وحرّك حتى يمتزج جيدًا.","في هذه الأثناء، قشّر حبات البوبلانو. اصنع شقًّا واحدًا لعمل جيب وأخرج البذور. احشُ كل فلفلة بربع خليط الفطر وغطِّها بملعقة كبيرة من الجبن.","اشوِ الفلفل المحشو على بعد 4 بوصات من مصدر الحرارة حتى يسخن الحشو ويبدأ الجبن بالذوبان، لمدة 4 دقائق تقريبًا."],[],[])))
